      "id": "estandard_integracio_react",
      "title": "estandard_integracio_react",
      "subtitle": "Lleis de pas i manual d'integració Plug & Play entre el mòdul Pedra Seca i la SPA React de Sollutia.",
      "categoryId": "cat_3",
